export type CapabilityFact={id:string;projection:string[];keywords:string[];requiresProof:boolean;availability:'LIVE'|'READY'|'DEGRADED'|'UNPROVEN'|'UNAVAILABLE'};
export function contextualCapabilities(intent:string,projection:string,facts:CapabilityFact[]){const q=intent.toLowerCase();return facts.map(f=>({f,score:(f.projection.includes(projection)?4:0)+f.keywords.reduce((n,k)=>n+(q.includes(k.toLowerCase())?1:0),0)+(f.availability==='LIVE'?2:f.availability==='READY'?1:0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).map(x=>x.f)}
